;;; ivm-lib.asm - runtime library for JIT generated code (ivm-jit.c)
;;;
;;; (<) 2026 Jonas S Karlsson
;;;
;;; Generated by Claude

;;; Link this FIRST (before ivm.c) so it sits at a fixed address:
;;;
;;;   cl65 -t sim6502 -DJIT -o ivm-jit ivm-lib.asm ivm.c
;;;   cl65 -t atmos   -DJIT -o ivm-jit.tap ivm-lib.asm ivm.c
;;;
;;; Note: Newer cc65 renamed the C stack pointer sp -> c_sp:
;;;  add -Wa -DUSE_C_SP
;;;
;;; An -o image copies a part of _ivmlib_init .. _ivmlib_end verbatim
;;; (from the startup it needs to a cut), so NOTHING here may reference code outside
;;; that range (no cc65 runtime/lib calls). Allowed: zero page, ROM,
;;; sim65 paravirt hooks (_write/_read/exit are fixed hook addresses,
;;; not code).
;;;
;;; TODO: it's not clear how it'll do that when compiling on host. LOL
;;;   maybe keep/save a copy of this binary as a stub artifact to
;;;   include. One problem is that the way it's written is not
;;;   relocatable. Entry points is one thing, however, internally
;;;   in eacch routine... should only be using relative jumps,
;;;   and possibly not depend on eachother?
;;;
;;;
;;; Calling convention (AX = A lo, X hi, as the JIT code keeps ACC):
;;;
;;;   opmul opdiv opmod : JT = first (ACC), AX = second,  AX = result
;;;                       (/0: AX = first, like the VM)
;;;   opputnum opputs   : AX = number / string,   AX kept
;;;   opputchar         : A = char,               A X Y preserved,
;;;                       Z/N from A (callers BNE on it: a char is never 0)
;;;   opgetchar         : AX = char, $FFFF = EOF
;;;   opprintstr        : JSR + inline string + 0, AX preserved
;;;   opmalloc          : AX = bytes -> AX = zeroed ptr (0 = fail), bump heap
;;;   opfree            : AX = ptr, no-op
;;;   opmemset          : A = fill, X = full pages, Y = rest,
;;;                       _opmemset_adr = ptr + X*256 (last page);
;;;                       A kept, X = $FF, Y = 0
;;;
;;; Sizes and cycles: per routine (cycles: the JSR to it included;
;;; opputnum..opdiv measured in cpu6502.c, the rest estimated).
;;;
;;; Zero page: its own, set below (ZP_LIB), and JT.
;;;
;;;   sim65: never returns to the C program (in place: ivmlib_load
;;;     jumps; -o image: exit), so all zp is ours:
;;;       CSP      2  sim65's arg pointer (header byte 7): set to pvframe
;;;                   before each call, no C stack kept
;;;       ZP_LIB   6  ptr1 ptr2 tmp3/tmp4 (tmp1/tmp2, sreg: aliases)
;;;     -z mem[] must stay above (ivm.c checks _ivmlib_zplo).
;;;   atmos: the in-process run returns to C, and the ROM owns low zp:
;;;     cc65's own scratch (zeropage.inc), the one place known free.

.export _ivmlib_init, _ivmlib_zpclr, _ivmlib_zpinit, _ivmlib_start, _ivmlib_end
.export _ivmlib_exit
.export _ivmlib_entry, _ivmlib_heap, _ivmlib_heapend
.export _ivmlib_zpsrc, _ivmlib_zpdst, _ivmlib_zplen, _ivmlib_spzp
.export _ivmlib_zpclen, _ivmlib_zpcn, _ivmlib_zpcdst
.export _ivmlib_zplo
.export _ivmlib_load, _ivmlib_seg, _ivmlib_dst, _ivmlib_run
.export _ivmlib_cut0, _ivmlib_cut1, _ivmlib_cut2, _ivmlib_cut3, _ivmlib_cut4
.export _ivmlib_bssp, _ivmlib_bssr

.export _opmul, _opdiv, _opmod, _opputnum
.export _opputchar, _opgetchar, _opputs, _opprintstr
.export _opmalloc, _opfree
.export _opmemset, _opmemset_adr
.export _ivmlib_cut5, _ivmlib_args, _ivmlib_libv
.export _opmove, _opstrlen, _opstrcmp, _opstrncmp, _opmemcmp
.export _opstrchr, _opmemchr, _opstrcpy, _opstrncpy


;;; JIT scratch word (ivm-jit.c tmp1/tmp2): first operand of opmul/opdiv/opmod
JT = $FE


;;;  TODO: the compiler, either if native or ot
;;;    should be able to run, indepeneding of it's on "host"
;;;    unix using clang or not, and able to target any
;;;    system, at least when generating a file.
.if .defined(__SIM6502__) .or .defined(__SIM65C02__)
	;; .if .defined(__CC65___) ??? TODO:
        SIM = 1
        .import _write, _read, exit     ;; sim65 paravirt hooks

        ;; sim65's arg pointer: the running program's header names it, so
        ;; in place it is the compiler's c_sp (the -o header copies it)
.ifdef USE_C_SP
        .importzp c_sp
        CSP = c_sp
.else
        .importzp sp
        CSP = sp
.endif

        ;; lib scratch: our own, after CSP ($00/$01)
        ZP_LIB  = $02
        ZP_LIBN = 6
        ptr1    = ZP_LIB                ;; pointer: puts, load, div, malloc
        ptr2    = ZP_LIB+2              ;; pointer: load, mul, div, malloc
        tmp3    = ZP_LIB+4              ;; word: AX kept, mul result, mod flag
        tmp4    = ZP_LIB+5
        tmp1    = tmp3                  ;; length: load, malloc (no tmp3 there)
        tmp2    = tmp4
        sreg    = ptr2                  ;; printstr's AX (opputs: no ptr2)

        .assert CSP+2 <= ZP_LIB || CSP >= ZP_LIB+ZP_LIBN, lderror, "ivm-lib: CSP inside ZP_LIB"
.elseif .defined(__ATMOS__)
        .include "zeropage.inc"
        ROM_PRCHR  = $0238              ;; ROM 1.1: print char in X
        ROM_GETKEY = $023B              ;; ROM 1.1: get key (UNTESTED)
.else
        .error "ivm-lib: only sim6502/sim65c02/atmos supported"
.endif


.code

;;; ===========================================================================
;;; Stand-alone entry: load/reset/autorun address of an ivm -o image
;;;; ===========================================================================
;;; ===========================================================================
;;; Load in place (ivm.c jit_load, sim65 run in place): copy the -o image
;;; after the lib down to _ivmlib_dst (the image's end of the lib: a cut),
;;; then start it as if loaded (_ivmlib_run: the image's first byte). The image
;;; is 4 segments (src, len): mem image, strings, gap (src 0: zeros), JIT
;;; code: no buffer to build it in. Before _ivmlib_init: not in -o images,
;;; not overwritten by the copy. Forward: the sources are above.  63 B + 16
;;; ===========================================================================
_ivmlib_seg:     .res 16                ;; 4 x (src, len)
_ivmlib_dst:     .word 0                ;; where: the image's lib end (a cut)
_ivmlib_spzp:                           ;; sim65 header needs sp's zp address
.ifdef SIM
                 .byte CSP
.else
                 .byte 0
.endif
_ivmlib_zplo:                           ;; -z mem[] from here up (lib zp below)
.ifdef SIM
                 .byte ZP_LIB+ZP_LIBN
.else
                 .byte 0
.endif

;;; x / y id (16 on): their routines, for the JIT to look the address up
;;; (ivm.c ivm_libv: the same order). Not in images (before _ivmlib_init)
_ivmlib_libv:
        .word   _opstrcmp, _opstrncmp, _opmemcmp, _opstrchr, _opmemchr
        .word   _opstrcpy, _opstrncpy

_ivmlib_load:
        lda     _ivmlib_dst
        sta     ptr2
        lda     _ivmlib_dst+1
        sta     ptr2+1
        ldx     #0
@seg:   cpx     #16
        beq     ldrun                   ;; all copied: run
        lda     _ivmlib_seg,x
        sta     ptr1
        lda     _ivmlib_seg+1,x
        sta     ptr1+1
        lda     _ivmlib_seg+2,x
        sta     tmp1                    ;; len lo
        lda     _ivmlib_seg+3,x
        sta     tmp2                    ;; len hi
        inx
        inx
        inx
        inx
        ldy     #0
@byte:  lda     tmp1                    ;; len-- (done at 0)
        bne     @n1
        lda     tmp2
        beq     @seg
        dec     tmp2
@n1:    dec     tmp1
        tya                             ;; A = 0 (the gap)
        ldy     ptr1+1
        beq     @z                      ;; src $00xx: zeros, src stays
        ldy     #0
        lda     (ptr1),y
        inc     ptr1
        bne     @z
        inc     ptr1+1
@z:     ldy     #0
        sta     (ptr2),y
        inc     ptr2
        bne     @byte
        inc     ptr2+1
        bne     @byte                   ;; always
ldrun:  jmp     _ivmlib_start           ;; patched: the image's first byte
_ivmlib_run = ldrun + 1


;;; ===========================================================================
;;; Startup. An image starts at the first part it needs (ivm.c jit_libbeg):
;;;   _ivmlib_init    static arrays: zeroed (needs memset: cut1)
;;;   _ivmlib_zpclr   -z: mem[] past the image's last non-0 byte zeroed
;;;   _ivmlib_zpinit  -z: mem[] image copied to zp
;;;   _ivmlib_start   run main, exit
;;; each falls into the next. Operands patched by ivm.c, no variables.
;;; ===========================================================================

;;; bss zero: opmemset with X pages, Y rest; ivm.c set _opmemset_adr to
;;; bss + pages * 256 (the last page)
;;; 10 B
_ivmlib_init:
        ldx     #0                      ;; patched: pages
_ivmlib_bssp = * - 1
        ldy     #0                      ;; patched: rest
_ivmlib_bssr = * - 1
        lda     #0                      ;; fill
        jsr     _opmemset

;;; -z: zero the live mem[] the image doesn't carry: from its last byte
;;; (the const cut) down to the image's bytes (memory isn't 0 at load:
;;; sim65 fills it with $FF). Equal: none
;;; 13 B
_ivmlib_zpclr:
        ldx     #0                      ;; patched: mem[] bytes
_ivmlib_zpclen = * - 1
        lda     #0
        beq     zpcl2                   ;; (always)
zpcl1:  sta     $00,x                   ;; patched: zp base - 1
_ivmlib_zpcdst = * - 1
        dex
zpcl2:  cpx     #0                      ;; patched: image bytes
_ivmlib_zpcn = * - 1
        bne     zpcl1

;;; -z: copy mem[] image to zp, down from the last byte. 0 bytes: none
;;; 12 B
_ivmlib_zpinit:
        ldx     #0                      ;; patched: bytes
_ivmlib_zplen = * - 1
        beq     _ivmlib_start
zpcp:   lda     $FFFF,x                 ;; patched: image - 1
_ivmlib_zpsrc = * - 2
        sta     $00,x                   ;; patched: zp base - 1
_ivmlib_zpdst = * - 1
        dex
        bne     zpcp

;;; JSR the JIT code, then exit (sim65: A = exit code) / back to BASIC.
;;; _ivmlib_exit: where the program is done (an emulator's breakpoint:
;;; ./oric counts the cycles from the image's start to it)
;;; SIM 9 B, ATMOS 4 B
_ivmlib_start:
.ifdef SIM
        ldx     #$FF                    ;; no C stack: pvio points CSP
        txs
        jsr     $FFFF                   ;; patched: JIT code start
_ivmlib_entry = * - 2
_ivmlib_exit:
        jmp     exit                    ;; A = exit code (lo of result)
.else
        jsr     $FFFF                   ;; patched: JIT code start
_ivmlib_entry = * - 2
_ivmlib_exit:
        rts                             ;; back to BASIC
.endif

;;; ---- cut 0: an -o image ends here if it calls nothing ----
_ivmlib_cut0:

;;; ===========================================================================
;;; m: memset. Self-moddifying (savas 1c/byte using LDA ,x instead of LDA (),y)
;;;
;;; A : fill byte
;;; Y : rest (i.e. low byte size)
;;; _opmemset_adr: pointer +
;;;
;;;   LDA #fill / LDY #rest / JSR _opmemset
;;;
;;; Algo: First rest of last page; full pages downwards.
;;; NOTE: Max 32K (because terminate by BPL)
;;; ===========================================================================

;;; Only called for large/variable sized memset

;;; 17 B; ~20 c + 10 c per byte + 11 c per page
_opmemset:
        cpy     #0
        beq     opms_page               ;; no rest
opms_loop:
        dey
opms_sta:
        sta     $FFFF,y                 ;; operand patched by the caller
        bne     opms_loop
opms_page:
        dec     opms_sta+2              ;; next page down
        dex
        bpl     opms_loop
        rts
_opmemset_adr = opms_sta + 1

;;; ---- cut 1: ... no printing ----
_ivmlib_cut1:

pcbuf:  .byte   0                       ;; char for putchar/getchar
pcx:    .byte   0
pcy:    .byte   0

;;; ===========================================================================
;;; Character I/O trampolines
;;; ===========================================================================

;;; SIM 27 B, ATMOS 34 B; ~50 c + pvio + _write (SIM) / ROM
_opputchar:
        sta     pcbuf
        stx     pcx
        sty     pcy
.ifdef SIM
        ldx     #1                      ;; stdout
        jsr     pvio
        jsr     _write                  ;; write(1, &pcbuf, 1)
.else
        cmp     #$0A                    ;; LF -> CR LF
        bne     @ch
        ldx     #$0D
        jsr     ROM_PRCHR
@ch:    ldx     pcbuf
        jsr     ROM_PRCHR
.endif
        ldy     pcy
        ldx     pcx
        lda     pcbuf                   ;; last: Z/N from the char
        rts

.ifdef SIM
;;; the args (buf=&pcbuf, fd=X) as a static frame: CSP points at it, the
;;; hook pops them from there (and moves CSP: set again each call).
;;; AX = count 1. No C stack.
;;; 16 B + 4 B frame, ~24 c
pvio:   stx     pvfd                    ;; fd lo (hi stays 0)
        lda     #<pvframe
        sta     CSP
        lda     #>pvframe
        sta     CSP+1
        lda     #1
        ldx     #0
        rts

pvframe: .word  pcbuf                   ;; buf
pvfd:    .word  0                       ;; fd
.endif

;;; ---------------------------------------------------------------------------
;;; ": JSR _opprintstr / .asciiz "..." / next instruction: via opputs
;;; 30 B; ~90 c + ~24 c per char + opputchar

_opprintstr:
        sta     sreg                    ;; AX kept for the return
        stx     sreg+1
        pla                             ;; -> last byte of the JSR
        clc
        adc     #1
        tay
        pla
        adc     #0
        tax
        tya                             ;; AX -> the string
        jsr     _opputs                 ;; ptr1 -> its 0
        inc     ptr1                    ;; past it: the next instruction
        bne     :+
        inc     ptr1+1
:       lda     sreg
        ldx     sreg+1
        jmp     (ptr1)

;;; ---------------------------------------------------------------------------
;;; .: print AX unsigned decimal, AX kept
;;; 53 B; 0-9: 425 c, 42: 815 c, 1234: 1631 c, 65535: 2063 c; + opputchar

_opputnum:
        sta     tmp3                    ;; AX kept for the return
        stx     tmp4
        sta     ptr1
        stx     ptr1+1
        lda     #0
        pha                             ;; end marker
@div:   lda     #0                      ;; ptr1 /= 10, A = remainder
        ldx     #16
@bit:   asl     ptr1
        rol     ptr1+1
        rol     a
        cmp     #10
        bcc     @nb
        sbc     #10                     ;; C=1
        inc     ptr1
@nb:    dex
        bne     @bit
        ora     #'0'
        pha
        lda     ptr1
        ora     ptr1+1
        bne     @div
@out:   pla
        beq     retax
        jsr     _opputchar
        bne     @out                    ;; A kept: a digit, never 0
retax:  lda     tmp3                    ;; AX as on entry
        ldx     tmp4
        rts

;;; ---------------------------------------------------------------------------
;;; P: print 0-terminated string at AX, AX kept
;;; 31 B; ~40 c + ~24 c per char + opputchar

_opputs:
        sta     tmp3
        stx     tmp4
        sta     ptr1
        stx     ptr1+1
        ora     ptr1+1
        beq     retax                   ;; NULL
@l:     ldy     #0
        lda     (ptr1),y
        beq     retax
        jsr     _opputchar
        inc     ptr1
        bne     @l
        inc     ptr1+1
        bne     @l
        beq     retax                   ;; wrapped past $FFFF


;;; ---- cut 2: ... no mul/div/mod ----
_ivmlib_cut2:
;;; ===========================================================================
;;; Arithmetic: JT = first (ACC), AX = second, AX = result (unsigned 16 bit)
;;; ===========================================================================

;;; JT * AX. AX is the multiplier, shifted right until it is 0: one round
;;; per bit of AX, so the smaller number belongs in AX (the JIT puts a
;;; constant there). JT is destroyed.
;;; 44 B; 63-847 c: *10: 197 c, *255: 439 c, *65535: 847 c
_opmul:
        sta     ptr2                    ;; multiplier
        stx     ptr2+1
        lda     #0
        sta     tmp3                    ;; result
        sta     tmp4
@l:     lsr     ptr2+1
        ror     ptr2
        bcc     @n
        clc
        lda     tmp3
        adc     JT
        sta     tmp3
        lda     tmp4
        adc     JT+1
        sta     tmp4
@n:     asl     JT
        rol     JT+1
        lda     ptr2
        ora     ptr2+1
        bne     @l
        lda     tmp3
        ldx     tmp4
        rts

;;; JT / AX (opdiv) and JT % AX (opmod): one routine, opmod enters with
;;; C = 1 (the BIT skips opdiv's CLC). Quotient in JT, remainder in ptr1.
;;; AX = 0: AX = JT (unchanged, as the VM).
;;; 70 B; /0: 37 c, else 16 rounds: up to 1045 c
_opmod:
        sec                             ;; remainder
        .byte   $24                     ;; BIT zp: skips the CLC
_opdiv:
        clc                             ;; quotient
        ror     tmp3                    ;; bit 7: 1 = opmod
        sta     ptr2                    ;; divisor
        stx     ptr2+1
        ora     ptr2+1
        beq     @ja                     ;; /0
        lda     #0
        sta     ptr1
        sta     ptr1+1
        ldx     #16
@l:     asl     JT
        rol     JT+1
        rol     ptr1
        rol     ptr1+1
        php                             ;; C: 17th remainder bit
        lda     ptr1
        sec
        sbc     ptr2
        tay
        lda     ptr1+1
        sbc     ptr2+1
        bcs     @take                   ;; rem >= divisor
        plp
        bcc     @next                   ;; rem < divisor (no 17th bit)
        php                             ;; 17th bit: must subtract
@take:  plp
        sta     ptr1+1
        sty     ptr1
        inc     JT                      ;; quotient bit
@next:  dex
        bne     @l
        bit     tmp3
        bpl     @ja                     ;; opdiv: quotient
        lda     ptr1                    ;; opmod: remainder
        ldx     ptr1+1
        rts
@ja:    lda     JT
        ldx     JT+1
        rts



;;; ---- cut 3: ... no malloc/free ----
_ivmlib_cut3:

;;; ===========================================================================
;;; Heap: bump allocator, zeroed (calloc), even sizes. free is a no-op.
;;; ===========================================================================

;;; 106 B; ~120 c + 11 c per byte zeroed
_opmalloc:
        clc
        adc     #1
        and     #$FE
        sta     tmp1
        txa
        adc     #0
        sta     tmp2                    ;; tmp2:tmp1 = (n+1) & ~1
        bcs     @null                   ;; n = $FFFF
        ora     tmp1
        beq     @null                   ;; n = 0
        clc
        lda     _ivmlib_heap
        adc     tmp1
        sta     ptr2
        lda     _ivmlib_heap+1
        adc     tmp2
        sta     ptr2+1                  ;; ptr2 = new top
        bcs     @null
        lda     _ivmlib_heapend
        cmp     ptr2
        lda     _ivmlib_heapend+1
        sbc     ptr2+1
        bcc     @null                   ;; heapend < new top
        lda     _ivmlib_heap
        sta     ptr1
        lda     _ivmlib_heap+1
        sta     ptr1+1
        lda     #0
        tay
        ldx     tmp2                    ;; full pages
        beq     @part
@page:  sta     (ptr1),y
        iny
        bne     @page
        inc     ptr1+1
        dex
        bne     @page
@part:  ldy     tmp1                    ;; rest
        beq     @done
@byte:  dey
        sta     (ptr1),y
        bne     @byte
@done:  lda     _ivmlib_heap            ;; result = old heap
        ldx     _ivmlib_heap+1
        pha
        lda     ptr2
        sta     _ivmlib_heap
        lda     ptr2+1
        sta     _ivmlib_heap+1
        pla
        rts
@null:  lda     #0
        tax
        rts

;;; TODO: make it reuse, lol
;;; 1 B; 12 c
_opfree:
        rts

_ivmlib_heap:    .word 0                ;; next free heap byte
_ivmlib_heapend: .word 0                ;; first byte after heap



;;; ---- cut 4: ... no getchar (the image's end then: _ivmlib_end) ----
_ivmlib_cut4:

;;; ===========================================================================
;;; getchar: the last tier (an image with it ends at _ivmlib_end). Uses
;;; pvio / pcbuf (cut 2: below, so in such an image)
;;; ===========================================================================

;;; SIM 22 B, ATMOS 17 B
_opgetchar:
.ifdef SIM
        ldx     #0                      ;; stdin
        jsr     pvio
        jsr     _read                   ;; AX = read(0, &pcbuf, 1)
        cmp     #1
        bne     @eof
        lda     pcbuf
        ldx     #0
        rts
@eof:   lda     #$FF
        tax
        rts
.else
@wait:  jsr     ROM_GETKEY              ;; N=1: a key, its code in the low 7
        bpl     @wait
        and     #$7F
        ldx     $0209                   ;; ROM: $A5 while FUNCT is held
        cpx     #$A5
        bne     @key
        ora     #$80                    ;; FUNCT-x: hi bit (as cc65's getchar)
@key:   ldx     #0
        rts
.endif

;;; ---- cut 5: ... no string / memory routines (else: _ivmlib_end) ----
_ivmlib_cut5:

;;; ===========================================================================
;;; Strings and memory (ivm.c: V $ x y..
;;;
;;; The arguments in _ivmlib_args:
;;;
;;;    (a0 a1 a2 last i from ACC???)
;;; 
;;;    => the result in AX.
;;; 
;;; Families, each falling into the last with default set
;;; 
;;; (n: $FFFF, stop at a NUL):
;;;
;;;   strcmp > strncmp > memcmp     0, 1 or $FFFF (-1)
;;;   strchr > memchr               the address, 0: not there
;;;   strcpy > strncpy              d (strncpy: NULs up to n, as C)
;;; ===========================================================================

;;; TODO: zeropage? why not use tmp? and the index slot refs?
;;; TODO: actually instead of copying cheaper to PHA TXA PHA !!!!
;;;   (same cycles but 3 bytes instead of 4)
_ivmlib_args:   .res    6               ;; a0 a1 a2


sflag:          .byte   0               ;; 1: stop at a NUL (str..)
spad:           .byte   0               ;; strncpy: past the NUL, NULs

;;; ptr1 = a0, ptr2 = a1, tmp3/tmp4 = a2 (a count), Y = 0
;;; This to call if you have 3 args?
;;; TODO: if this was on stacK: PLA sta zp PLA sta azp ...
sargs:  lda     _ivmlib_args
        sta     ptr1
        lda     _ivmlib_args+1
        sta     ptr1+1
        lda     _ivmlib_args+2
        sta     ptr2
        lda     _ivmlib_args+3
        sta     ptr2+1
        lda     _ivmlib_args+4
        sta     tmp3
        lda     _ivmlib_args+5
        sta     tmp4
        ldy     #0
        rts

;;; the count - 1; Z = 1: it was 0 (done, left 0)
ndec:   lda     tmp3
        bne     @lo
        lda     tmp4
        beq     @z
        dec     tmp4
@lo:    dec     tmp3
        lda     #1
@z:     rts

;;; no limit: a2 = $FFFF
nmax:   lda     #$FF
        sta     _ivmlib_args+4
        sta     _ivmlib_args+5
        rts

;;; memmove(d, s, n) = memcpy too: from the end if d > s (they may overlap)
_opmove:
;;;  massive assembly, comment
        jsr     sargs

        lda     ptr2
        cmp     ptr1
        lda     ptr2+1
        sbc     ptr1+1
        bcc     @back                   ;; s < d
@fwd:   jsr     ndec
        beq     @done
        lda     (ptr2),y
        sta     (ptr1),y
        inc     ptr1
        bne     :+
        inc     ptr1+1
:       inc     ptr2
        bne     @fwd
        inc     ptr2+1
        bne     @fwd                    ;; (always)
@back:  clc                             ;; past both ends, then down
        lda     ptr1
        adc     tmp3
        sta     ptr1
        lda     ptr1+1
        adc     tmp4
        sta     ptr1+1
        clc
        lda     ptr2
        adc     tmp3
        sta     ptr2
        lda     ptr2+1
        adc     tmp4
        sta     ptr2+1
@bk:    jsr     ndec
        beq     @done
        lda     ptr1
        bne     :+
        dec     ptr1+1
:       dec     ptr1
        lda     ptr2
        bne     :+
        dec     ptr2+1
:       dec     ptr2
        lda     (ptr2),y
        sta     (ptr1),y
        jmp     @bk
@done:  lda     _ivmlib_args
        ldx     _ivmlib_args+1
        rts

;;; strlen(s)
_opstrlen:
        lda     _ivmlib_args
        sta     ptr1
        lda     _ivmlib_args+1
        sta     ptr1+1

;;; TODO: this is bad implenmtnation, keep count in X hi and Y low

        ldy     #0
        sty     tmp3
        sty     tmp4
@l:     lda     (ptr1),y
        beq     @d
        inc     ptr1
        bne     :+
        inc     ptr1+1
:       inc     tmp3
        bne     @l
        inc     tmp4
        bne     @l                      ;; (always)
@d:     lda     tmp3
        ldx     tmp4
        rts

;;; strcmp(a, b) > strncmp(a, b, n) > memcmp(a, b, n)
_opstrcmp:
        jsr     nmax

_opstrncmp:
        ldx     #1
        .byte   $2C                     ;; BIT abs: skips the ldx #0
_opmemcmp:
        ldx     #0
        stx     sflag

        jsr     sargs

@l:     jsr     ndec
        beq     @eq                     ;; n done: equal
        lda     (ptr1),y
        cmp     (ptr2),y
        bne     @ne
        ldx     sflag
        beq     :+
        cmp     #0
        beq     @eq                     ;; both at their NUL
:       inc     ptr1
        bne     :+
        inc     ptr1+1
:       inc     ptr2
        bne     @l
        inc     ptr2+1
        bne     @l                      ;; (always)
@ne:    bcc     @lt                     ;; a < b
        lda     #1
        ldx     #0
        rts
@lt:    lda     #$FF
        tax
        rts
@eq:    lda     #0
        tax
        rts

;;; strchr(s, c) > memchr(s, c, n)
_opstrchr:
        jsr     nmax

        ldx     #1
        .byte   $2C
_opmemchr:
        ldx     #0
        stx     sflag
        jsr     sargs                   ;; ptr2: c (its lo)
@l:     jsr     ndec
        beq     @no
        lda     (ptr1),y
        cmp     ptr2
        beq     @yes                    ;; (c may be the NUL)
        ldx     sflag
        beq     :+
        cmp     #0
        beq     @no
:       inc     ptr1
        bne     @l
        inc     ptr1+1
        bne     @l                      ;; (always)
@yes:   lda     ptr1
        ldx     ptr1+1
        rts
@no:    lda     #0
        tax
        rts

;;; strcpy(d, s) > strncpy(d, s, n)
_opstrcpy:
        jsr     nmax
        ldx     #1
        .byte   $2C
_opstrncpy:
        ldx     #0
        stx     sflag

        jsr     sargs

        sty     spad                    ;; (Y = 0)
@l:     jsr     ndec
        beq     @done
        lda     spad
        bne     @z                      ;; past the NUL: NULs
        lda     (ptr2),y
        sta     (ptr1),y
        tax                             ;; Z: the NUL?
        inc     ptr2
        bne     :+
        inc     ptr2+1
:       txa
        bne     @nx
        lda     sflag                   ;; the NUL: strcpy stops
        bne     @done
        inc     spad
        bne     @nx                     ;; (always)
@z:     lda     #0
        sta     (ptr1),y
@nx:    inc     ptr1
        bne     @l
        inc     ptr1+1
        bne     @l                      ;; (always)
@done:  lda     _ivmlib_args
        ldx     _ivmlib_args+1
        rts


_ivmlib_end:
